describe('Modal Dialog Animation', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('button.open-modal').click(); // Replace with the actual selector to open the modal
    });

    it('should open the modal with animation', () => {
        cy.get('.modal') // Replace with the actual selector for the modal
            .should('be.visible')
            .and('have.class', 'fade-in'); // Assuming 'fade-in' is the class for animation
    });

    it('should close the modal when the close button is clicked', () => {
        cy.get('.modal .close-button').click(); // Replace with the actual selector for the close button
        cy.get('.modal').should('not.be.visible');
    });
});
